// Generated by OrchestKit Claude Plugin
// Created: 2026-08-21

// Guards the "developer resource discoverability" recovery. The audit FAILED
// this check: "Agent searched for 'yonyon' developer resources but found
// nothing relevant." /developers and /yonyon already existed, were in the
// sitemap and were listed in llms.txt, what was missing was that an agent
// following THIS SITE'S OWN documented convention ("append .md to a page URL")
// got an HTML 404 for /developers.md. Verified against production 2026-08-21:
//   curl -s -o /dev/null -w '%{http_code} %{content_type}' .../developers.md
//   → 404 text/html; charset=utf-8
//
// So these tests pin two things: the twins exist and carry the names a
// name-based query uses, and the HTML pages keep naming the product + studio.

import { readFileSync, readdirSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { SERVED_EXACT } from "@/lib/agent-404";
import { DEVELOPER_RESOURCES } from "@/lib/developer-resources";
import {
	MARKDOWN_TWIN_SLUGS,
	hasMarkdownTwin,
	pageMarkdown,
} from "@/lib/page-markdown";
import { STATIC_PAGES } from "@/lib/static-pages";
import { YONYON_FAQS } from "@/lib/yonyon-faqs";

const APP = resolve(__dirname, "../app");

describe("Markdown twin registry", () => {
	it("every twin slug is a real (home) page", () => {
		const homeDirs = readdirSync(resolve(APP, "(home)"), {
			withFileTypes: true,
		})
			.filter((e) => e.isDirectory())
			.map((e) => e.name);
		for (const slug of MARKDOWN_TWIN_SLUGS) {
			expect(homeDirs, `twin without a page: ${slug}`).toContain(slug);
		}
	});

	it("every twin slug is in the sitemap and the served allowlist", () => {
		for (const slug of MARKDOWN_TWIN_SLUGS) {
			expect(STATIC_PAGES).toContain(`/${slug}`);
			expect(SERVED_EXACT.has(`/${slug}.md`)).toBe(true);
		}
	});

	it("hasMarkdownTwin never claims a page that owns its own .md route", () => {
		// /pricing.md, /auth.md and /api-policy.md are real handlers. A twin claim
		// here would make middleware shadow them with a rewrite.
		for (const slug of ["pricing", "auth", "api-policy", "about", "terms"]) {
			expect(hasMarkdownTwin(slug), `must not claim ${slug}`).toBe(false);
		}
	});
});

describe("/developers.md", () => {
	const md = pageMarkdown("developers");

	it("names both the product and the studio in the H1", () => {
		// This is the whole point: a name-keyed query ("yonyon developer
		// resources") has to match something at the head of the document.
		// Read as the H1 LINE rather than line 0: the document now opens with a
		// frontmatter block, so line 0 is `---`. The requirement was always about
		// the heading, and anchoring it to a line index quietly made it about
		// the file's first byte instead.
		const h1 = md.split("\n").find((l) => l.startsWith("# ")) as string;
		expect(h1).toContain("OrchestKit");
		expect(h1).toContain("Yonyon");
	});

	it("carries the same brand names in its frontmatter title", () => {
		// The header block is what a Markdown consumer reads as the document
		// title, so the name-keyed query has to match there too.
		const title = md.split("\n").find((l) => l.startsWith("title: ")) as string;
		expect(title).toContain("OrchestKit");
		expect(title).toContain("Yonyon");
	});

	it("lists every resource the HTML page lists, from the same source", () => {
		expect(DEVELOPER_RESOURCES.length).toBeGreaterThan(5);
		for (const r of DEVELOPER_RESOURCES) {
			expect(md, `missing resource: ${r.title}`).toContain(r.title);
		}
	});

	it("uses absolute URLs so a fetched copy stays navigable", () => {
		expect(md).toContain("https://orchestkit.yonyon.ai/api/openapi");
		expect(md).not.toMatch(/\]\(\/[a-z]/);
	});

	it("states the agent contract: no auth, RateLimit headers, api-policy", () => {
		expect(md).toContain("RateLimit-");
		expect(md).toContain("/api-policy");
		expect(md).toMatch(/no credentials/i);
	});
});

describe("/yonyon.md", () => {
	const md = pageMarkdown("yonyon");

	it("leads with the brand disambiguation, not the product pitch", () => {
		// H1 line, not line 0 — the document opens with a frontmatter block now.
		expect(md.split("\n").find((l) => l.startsWith("# "))).toContain("Yonyon");
		expect(md.split("\n").find((l) => l.startsWith("title: "))).toContain(
			"Yonyon",
		);
		expect(md).toMatch(/not the musician/i);
	});

	it("carries every FAQ question and answer from the shared source", () => {
		for (const faq of YONYON_FAQS) {
			expect(md).toContain(faq.question);
			expect(md).toContain(faq.answer);
		}
	});

	it("links the developer hub and its Markdown twin", () => {
		expect(md).toContain("https://orchestkit.yonyon.ai/developers");
		expect(md).toContain("https://orchestkit.yonyon.ai/developers.md");
	});
});

describe("HTML pages keep the names a search engine matches on", () => {
	it("/developers spells the studio name in its <title>", () => {
		const src = readFileSync(
			resolve(APP, "(home)/developers/page.tsx"),
			"utf8",
		);
		expect(src).toMatch(/title:\s*"[^"]*Yonyon[^"]*"/);
	});

	it("/developers no longer promises Markdown on 'any page URL'", () => {
		// That claim was false for every non-/docs page and is what sent an agent
		// to an HTML 404. It must stay scoped to what is actually served.
		const src = readFileSync(
			resolve(APP, "(home)/developers/page.tsx"),
			"utf8",
		);
		expect(src).not.toContain("appending .md to any page URL");
		expect(src).toContain("/developers.md");
	});

	it("both pages render from the shared data modules, not private copies", () => {
		const devSrc = readFileSync(resolve(APP, "(home)/developers/page.tsx"), "utf8");
		const yonSrc = readFileSync(resolve(APP, "(home)/yonyon/page.tsx"), "utf8");
		expect(devSrc).toContain("@/lib/developer-resources");
		expect(yonSrc).toContain("@/lib/yonyon-faqs");
	});
});

describe("llms.txt advertises the twins", () => {
	it("links /developers.md and /yonyon.md", () => {
		const src = readFileSync(resolve(APP, "llms.txt/route.ts"), "utf8");
		expect(src).toContain("/developers.md");
		expect(src).toContain("/yonyon.md");
	});
});
